text:
{
  "claims": [
    {
      "anchor": "In March 2026 a SQLite developer found and fixed a rare corruption bug",
      "claim_text": "In March 2026 a SQLite developer found and fixed a rare corruption bug.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S0 states Dan found and fixed a rare corruption bug on 2026-03-03."
    },
    {
      "anchor": "known as the WAL-reset bug",
      "claim_text": "The bug is known as the WAL-reset bug.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S1 names it the WAL-reset bug."
    },
    {
      "anchor": "It is likely present in every release from 3.7.0 through 3.51.2",
      "claim_text": "The bug is likely present in all versions from 3.7.0 through 3.51.2.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S0 says likely present in all versions 3.7.0 through 3.51.2."
    },
    {
      "anchor": "is fixed in 3.51.3 and later",
      "claim_text": "The bug is fixed in version 3.51.3 and later.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P1.S1 states fixed in 3.51.3 and later."
    },
    {
      "anchor": "with backports available for 3.44.6 and 3.50.6",
      "claim_text": "Backports of the fix are available for 3.44.6 and 3.50.6.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P1.S2 lists 3.50.7, not 3.50.6."
    },
    {
      "anchor": "The bug can only occur when two or more connections in separate threads or processes try to write or checkpoint at the same instant",
      "claim_text": "The bug can only occur when two or more connections in separate threads or processes try to write or checkpoint at the same instant.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S0 gives these as the only conditions."
    },
    {
      "anchor": "it affects rollback-journal databases as well as WAL databases",
      "claim_text": "The bug affects rollback-journal databases as well as WAL databases.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P2.S0 says the bug only affects WAL mode databases."
    },
    {
      "anchor": "The developers reproduced it organically in the lab before writing the fix",
      "claim_text": "The developers reproduced the bug organically in the lab before writing the fix.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S2", "rel": "refutes"},
        {"sid": "P8.S1", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P3.S2 and P8.S1 say they were unable to reproduce it organically."
    },
    {
      "anchor": "it was assigned a CVE identifier",
      "claim_text": "The bug was assigned a CVE identifier.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions a CVE."
    },
    {
      "anchor": "Phil Eaton later published a reproducer that does not need the special testing code hack",
      "claim_text": "Phil Eaton later published a reproducer that does not need the special testing code hack.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P9.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P9.S0 says Phil Eaton devised a reproducer without the testing code hack."
    },
    {
      "anchor": "Because the consequences are serious, the SQLite developers describe upgrading as an emergency",
      "claim_text": "The SQLite developers describe upgrading as an emergency.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P10.S1", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P10.S1 says it is not an emergency."
    }
  ]
}
